import { defineRoute } from "@kasperrt/smolter/preact";
import { configureApplication, mountApplication } from "@kasperrt/smolter/preact/client";
import * as home from "./routes/_index/route";

configureApplication({
  isDocumentHandoff: (from, to) =>
    from.origin !== to.origin && to.origin === "https://account.example",
});

const routes = [defineRoute("/", home)];

await mountApplication(routes);
